// カード削除
async function deleteCardWithCourse(cardId, courseId) {
  if (!confirm('このカードを削除してもよろしいですか？')) {
    return
  }
  
  try {
    await axios.delete(`/api/cards/${cardId}`)
    alert('カードを削除しました')
    loadCardManagementPage(courseId)
  } catch (error) {
    console.error('Error deleting card:', error)
    alert('削除に失敗しました')
  }
}

