  const totalCards = courses.reduce((sum, course) => sum + (course.cards?.length || 0), 0)
  const totalHints = courses.reduce((sum, course) => {
    return sum + (course.cards || []).reduce((hintSum, card) => {
      return hintSum + (card.hints?.length || 0)
    }, 0)
  }, 0)
  
  // モデル名を読みやすく変換
