// 削除済み: 重複していた古いaddOptionalProblem関数（13610行目の新バージョンを使用）

// ============================================
// 認証機能
// ============================================

// APIリクエストヘルパー（認証トークン付き）
async function authFetch(url, options = {}) {
  const headers = {
    'Content-Type': 'application/json',
    ...options.headers
  }
  
  if (state.auth.sessionToken) {
    headers['Authorization'] = `Bearer ${state.auth.sessionToken}`
  }
  
  const response = await fetch(url, {
    ...options,
    headers
  })
  
  // 401エラー（認証切れ）の場合、リフレッシュを試みる
  if (response.status === 401 && state.auth.refreshToken) {
    const refreshed = await refreshSession()
    if (refreshed) {
      // リトライ
      headers['Authorization'] = `Bearer ${state.auth.sessionToken}`
      return fetch(url, { ...options, headers })
    } else {
      // リフレッシュ失敗: ログアウト
      logout()
      return response
    }
  }
  
  return response
}

// セッション検証
async function verifySession() {
  try {
    const response = await authFetch('/api/auth/me')
    if (!response.ok) {
      logout()
    }
  } catch (error) {
    console.error('セッション検証エラー:', error)
    logout()
  }
}

// セッション更新
async function refreshSession() {
  try {
    const response = await fetch('/api/auth/refresh', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ refresh_token: state.auth.refreshToken })
    })
    
    if (!response.ok) {
      return false
    }
    
    const data = await response.json()
    state.auth.sessionToken = data.session_token
    localStorage.setItem('session_token', data.session_token)
    
    return true
  } catch (error) {
    console.error('セッション更新エラー:', error)
    return false
  }
}

