// ============================================
// Phase 15B: 画像編集＋複数アップロード＋サムネイル
// ============================================

// 画像編集状態
let imageEditorState = {
  originalImage: null,
  editedCanvas: null,
  rotation: 0,
  scale: 1.0,
  brightness: 1.0,
  contrast: 1.0,
  filter: 'none'
}

// 画像編集モーダル表示
function showImageEditor(file) {
  const reader = new FileReader()
  reader.onload = (e) => {
    const img = new Image()
    img.onload = () => {
      imageEditorState.originalImage = img
      imageEditorState.rotation = 0
      imageEditorState.scale = 1.0
      imageEditorState.brightness = 1.0
      imageEditorState.contrast = 1.0
      imageEditorState.filter = 'none'
      imageEditorState.cropMode = false
      imageEditorState.cropStart = null
      imageEditorState.cropEnd = null
      
      const modalHTML = `
        <div id="image-editor-modal" class="fixed inset-0 bg-black bg-opacity-90 flex items-center justify-center z-50 p-4">
          <div class="bg-white rounded-lg w-full max-w-5xl max-h-screen overflow-hidden flex flex-col">
            <div class="p-4 border-b flex justify-between items-center">
              <h2 class="text-xl font-bold">🖼️ 画像編集</h2>
              <button onclick="closeImageEditor()" class="text-gray-500 hover:text-gray-700">
                <i class="fas fa-times text-2xl"></i>
              </button>
            </div>
            
            <div class="flex-1 overflow-auto p-4 bg-gray-100">
              <div class="flex justify-center">
                <canvas id="image-editor-canvas" class="max-w-full max-h-96 border-2 border-gray-300 bg-white"></canvas>
              </div>
            </div>
            
            <div class="p-4 border-t bg-gray-50 max-h-64 overflow-y-auto">
              <div class="grid grid-cols-2 gap-4 mb-4">
                <div>
                  <label class="block text-sm font-medium mb-2">明度: <span id="brightness-value">100</span>%</label>
                  <input type="range" id="brightness-slider" min="0" max="200" value="100" 
                         oninput="adjustBrightness(this.value)" class="w-full">
                </div>
                <div>
                  <label class="block text-sm font-medium mb-2">コントラスト: <span id="contrast-value">100</span>%</label>
                  <input type="range" id="contrast-slider" min="0" max="200" value="100" 
                         oninput="adjustContrast(this.value)" class="w-full">
                </div>
              </div>
              
              <div class="mb-4">
                <label class="block text-sm font-medium mb-2">フィルター</label>
                <select id="filter-select" onchange="applyFilter(this.value)" class="w-full px-3 py-2 border rounded">
                  <option value="none">なし</option>
                  <option value="grayscale">グレースケール</option>
                  <option value="sepia">セピア</option>
                  <option value="invert">反転</option>
                  <option value="blur">ぼかし</option>
                </select>
              </div>
              
              <div class="flex gap-2 mb-4 flex-wrap">
                <button onclick="toggleCropMode()" id="crop-toggle-btn" class="px-3 py-2 bg-indigo-600 text-white rounded hover:bg-indigo-700 text-sm">
                  <i class="fas fa-crop"></i> トリミング
                </button>
                <button onclick="rotateImage(-90)" class="px-3 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 text-sm">
                  <i class="fas fa-undo"></i> 左回転
                </button>
                <button onclick="rotateImage(90)" class="px-3 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 text-sm">
                  <i class="fas fa-redo"></i> 右回転
                </button>
                <button onclick="scaleImage(1.2)" class="px-3 py-2 bg-green-600 text-white rounded hover:bg-green-700 text-sm">
                  <i class="fas fa-search-plus"></i> 拡大
                </button>
                <button onclick="scaleImage(0.8)" class="px-3 py-2 bg-green-600 text-white rounded hover:bg-green-700 text-sm">
                  <i class="fas fa-search-minus"></i> 縮小
                </button>
                <button onclick="resetImageEditor()" class="px-3 py-2 bg-gray-600 text-white rounded hover:bg-gray-700 text-sm">
                  <i class="fas fa-sync"></i> リセット
                </button>
                <button onclick="applyCrop()" id="apply-crop-btn" class="px-3 py-2 bg-green-600 text-white rounded hover:bg-green-700 text-sm hidden">
                  <i class="fas fa-check"></i> トリミング適用
                </button>
              </div>
              
              <div class="flex gap-2 justify-end">
                <button onclick="closeImageEditor()" class="px-6 py-2 bg-gray-300 text-gray-700 rounded hover:bg-gray-400">
                  キャンセル
                </button>
                <button onclick="saveEditedImage()" class="px-6 py-2 bg-purple-600 text-white rounded hover:bg-purple-700">
                  <i class="fas fa-check"></i> 編集を適用
                </button>
              </div>
            </div>
          </div>
        </div>
      `
      
      document.body.insertAdjacentHTML('beforeend', modalHTML)
      renderImageEditor()
    }
    img.src = e.target.result
  }
  reader.readAsDataURL(file)
}

// 画像エディタをレンダリング
function renderImageEditor() {
  const canvas = document.getElementById('image-editor-canvas')
  if (!canvas || !imageEditorState.originalImage) return
  
  const ctx = canvas.getContext('2d')
  const img = imageEditorState.originalImage
  
  // Canvas サイズ設定
  const maxSize = 800
  let width = img.width
  let height = img.height
  
  if (width > maxSize || height > maxSize) {
    if (width > height) {
      height = (height / width) * maxSize
      width = maxSize
    } else {
      width = (width / height) * maxSize
      height = maxSize
    }
  }
  
  canvas.width = width * imageEditorState.scale
  canvas.height = height * imageEditorState.scale
  
  ctx.save()
  ctx.translate(canvas.width / 2, canvas.height / 2)
  ctx.rotate((imageEditorState.rotation * Math.PI) / 180)
  ctx.scale(imageEditorState.scale, imageEditorState.scale)
  
  // フィルター適用
  ctx.filter = `brightness(${imageEditorState.brightness}) contrast(${imageEditorState.contrast})`
  
  if (imageEditorState.filter === 'grayscale') {
    ctx.filter += ' grayscale(100%)'
  } else if (imageEditorState.filter === 'sepia') {
    ctx.filter += ' sepia(100%)'
  } else if (imageEditorState.filter === 'invert') {
    ctx.filter += ' invert(100%)'
  } else if (imageEditorState.filter === 'blur') {
    ctx.filter += ' blur(3px)'
  }
  
  ctx.drawImage(img, -width / 2, -height / 2, width, height)
  ctx.restore()
  
  // トリミング矩形を描画
  if (imageEditorState.cropMode && imageEditorState.cropStart && imageEditorState.cropEnd) {
    const startX = Math.min(imageEditorState.cropStart.x, imageEditorState.cropEnd.x)
    const startY = Math.min(imageEditorState.cropStart.y, imageEditorState.cropEnd.y)
    const rectWidth = Math.abs(imageEditorState.cropEnd.x - imageEditorState.cropStart.x)
    const rectHeight = Math.abs(imageEditorState.cropEnd.y - imageEditorState.cropStart.y)
    
    ctx.strokeStyle = '#FF0000'
    ctx.lineWidth = 2
    ctx.setLineDash([5, 5])
    ctx.strokeRect(startX, startY, rectWidth, rectHeight)
    ctx.setLineDash([])
    
    // 半透明オーバーレイ
    ctx.fillStyle = 'rgba(0, 0, 0, 0.3)'
    ctx.fillRect(0, 0, canvas.width, startY)
    ctx.fillRect(0, startY, startX, rectHeight)
    ctx.fillRect(startX + rectWidth, startY, canvas.width - (startX + rectWidth), rectHeight)
    ctx.fillRect(0, startY + rectHeight, canvas.width, canvas.height - (startY + rectHeight))
  }
  
  imageEditorState.editedCanvas = canvas
}

// 画像回転
function rotateImage(degrees) {
  imageEditorState.rotation += degrees
  renderImageEditor()
}

// 画像拡大縮小
function scaleImage(factor) {
  imageEditorState.scale *= factor
  imageEditorState.scale = Math.max(0.1, Math.min(3.0, imageEditorState.scale))
  renderImageEditor()
}

// リセット
function resetImageEditor() {
  imageEditorState.rotation = 0
  imageEditorState.scale = 1.0
  imageEditorState.brightness = 1.0
  imageEditorState.contrast = 1.0
  imageEditorState.filter = 'none'
  
  const brightnessSlider = document.getElementById('brightness-slider')
  const contrastSlider = document.getElementById('contrast-slider')
  const filterSelect = document.getElementById('filter-select')
  
  if (brightnessSlider) brightnessSlider.value = 100
  if (contrastSlider) contrastSlider.value = 100
  if (filterSelect) filterSelect.value = 'none'
  
  document.getElementById('brightness-value').textContent = '100'
  document.getElementById('contrast-value').textContent = '100'
  
  renderImageEditor()
}

// 明度調整
function adjustBrightness(value) {
  imageEditorState.brightness = value / 100
  document.getElementById('brightness-value').textContent = value
  renderImageEditor()
}

// コントラスト調整
function adjustContrast(value) {
  imageEditorState.contrast = value / 100
  document.getElementById('contrast-value').textContent = value
  renderImageEditor()
}

// フィルター適用
function applyFilter(filterName) {
  imageEditorState.filter = filterName
  renderImageEditor()
}

// 編集を保存
async function saveEditedImage() {
  if (!imageEditorState.editedCanvas) return
  
  imageEditorState.editedCanvas.toBlob(async (blob) => {
    const file = new File([blob], 'edited-image.png', { type: 'image/png' })
    fileUploadState.selectedImageFile = file
    
    closeImageEditor()
    previewImageFile(file)
    alert('✅ 編集が適用されました。「アップロードして追加」をクリックしてください。')
  }, 'image/png')
}

// トリミングモード切り替え
function toggleCropMode() {
  imageEditorState.cropMode = !imageEditorState.cropMode
  imageEditorState.cropStart = null
  imageEditorState.cropEnd = null
  
  const canvas = document.getElementById('image-editor-canvas')
  const toggleBtn = document.getElementById('crop-toggle-btn')
  const applyBtn = document.getElementById('apply-crop-btn')
  
  if (imageEditorState.cropMode) {
    toggleBtn.classList.add('bg-red-600', 'hover:bg-red-700')
    toggleBtn.classList.remove('bg-indigo-600', 'hover:bg-indigo-700')
    toggleBtn.innerHTML = '<i class="fas fa-times"></i> キャンセル'
    applyBtn.classList.remove('hidden')
    
    // Canvasにマウスイベントを追加
    canvas.style.cursor = 'crosshair'
    canvas.addEventListener('mousedown', startCrop)
    canvas.addEventListener('mousemove', drawCropRect)
    canvas.addEventListener('mouseup', endCrop)
  } else {
    toggleBtn.classList.remove('bg-red-600', 'hover:bg-red-700')
    toggleBtn.classList.add('bg-indigo-600', 'hover:bg-indigo-700')
    toggleBtn.innerHTML = '<i class="fas fa-crop"></i> トリミング'
    applyBtn.classList.add('hidden')
    
    canvas.style.cursor = 'default'
    canvas.removeEventListener('mousedown', startCrop)
    canvas.removeEventListener('mousemove', drawCropRect)
    canvas.removeEventListener('mouseup', endCrop)
  }
  
  renderImageEditor()
}

// トリミング開始
function startCrop(e) {
  if (!imageEditorState.cropMode) return
  
  const canvas = document.getElementById('image-editor-canvas')
  const rect = canvas.getBoundingClientRect()
  
  imageEditorState.cropStart = {
    x: e.clientX - rect.left,
    y: e.clientY - rect.top
  }
  imageEditorState.cropEnd = null
}

// トリミング範囲描画
function drawCropRect(e) {
  if (!imageEditorState.cropMode || !imageEditorState.cropStart) return
  
  const canvas = document.getElementById('image-editor-canvas')
  const rect = canvas.getBoundingClientRect()
  
  imageEditorState.cropEnd = {
    x: e.clientX - rect.left,
    y: e.clientY - rect.top
  }
  
  renderImageEditor()
}

// トリミング終了
function endCrop(e) {
  if (!imageEditorState.cropMode || !imageEditorState.cropStart) return
  
  const canvas = document.getElementById('image-editor-canvas')
  const rect = canvas.getBoundingClientRect()
  
  imageEditorState.cropEnd = {
    x: e.clientX - rect.left,
    y: e.clientY - rect.top
  }
  
  renderImageEditor()
}

// トリミング適用
function applyCrop() {
  if (!imageEditorState.cropStart || !imageEditorState.cropEnd) {
    alert('トリミング範囲を選択してください')
    return
  }
  
  const canvas = document.getElementById('image-editor-canvas')
  const ctx = canvas.getContext('2d')
  
  // トリミング範囲を計算
  const startX = Math.min(imageEditorState.cropStart.x, imageEditorState.cropEnd.x)
  const startY = Math.min(imageEditorState.cropStart.y, imageEditorState.cropEnd.y)
  const width = Math.abs(imageEditorState.cropEnd.x - imageEditorState.cropStart.x)
  const height = Math.abs(imageEditorState.cropEnd.y - imageEditorState.cropStart.y)
  
  if (width < 10 || height < 10) {
    alert('トリミング範囲が小さすぎます')
    return
  }
  
  // トリミング範囲の画像データを取得
  const imageData = ctx.getImageData(startX, startY, width, height)
  
  // 新しいCanvasに描画
  const tempCanvas = document.createElement('canvas')
  tempCanvas.width = width
  tempCanvas.height = height
  const tempCtx = tempCanvas.getContext('2d')
  tempCtx.putImageData(imageData, 0, 0)
  
  // 新しい画像として設定
  const newImg = new Image()
  newImg.onload = () => {
    imageEditorState.originalImage = newImg
    imageEditorState.cropMode = false
    imageEditorState.cropStart = null
    imageEditorState.cropEnd = null
    
    toggleCropMode() // モード解除
    renderImageEditor()
    alert('✅ トリミングが適用されました')
  }
  newImg.src = tempCanvas.toDataURL()
}

// 編集を保存（元の関数）
async function saveEditedImageOrig() {
  if (!imageEditorState.editedCanvas) return
  
  imageEditorState.editedCanvas.toBlob(async (blob) => {
    const file = new File([blob], 'edited-image.png', { type: 'image/png' })
    fileUploadState.selectedImageFile = file
    
    closeImageEditor()
    
    // プレビュー更新
    const reader = new FileReader()
    reader.onload = (e) => {
      const previewImg = document.getElementById('image-preview-img')
      const previewName = document.getElementById('image-preview-name')
      const previewDiv = document.getElementById('image-upload-preview')
      const uploadBtn = document.getElementById('upload-image-btn')
      
      if (previewImg && previewName && previewDiv && uploadBtn) {
        previewImg.src = e.target.result
        previewName.textContent = file.name + ' (' + formatFileSize(file.size) + ')'
        previewDiv.classList.remove('hidden')
        uploadBtn.classList.remove('hidden')
      }
    }
    reader.readAsDataURL(file)
    
    alert('✅ 画像編集を適用しました！\n\n「アップロード」ボタンでアップロードしてください。')
  }, 'image/png', 0.9)
}

